PAGE = dict(
    slug='y_auto_tick_decimals',
    title='Pane::y_auto_tick_decimals',
    signature='Pane& Pane::y_auto_tick_decimals(int decimals)\nPane& Pane::clear_y_auto_tick_decimals() noexcept',
    intro='Sets how many decimals the automatic tick labels of the y axis are written with, for the axis that uses plain numbers. Without a setting the renderer picks the fewest decimals that tell the ticks apart; with one, every automatic label has exactly that many, so a column of ticks lines up. The count is stored in `y_axis().auto_tick_decimals` (empty when unset), and `clear_y_auto_tick_decimals()` removes it, giving exactly the figure that never set it.\n\nThe count must be from 0 to 8; anything else throws `pluss::Error` and the stored count is kept. The setting shapes automatic labels in plain notation only. An axis whose numbers are written in scientific notation ([`y_tick_format`](y_tick_format.md) `Auto` on millions, or `Scientific`) is not changed by it, and explicit labels ([`y_ticks`](y_ticks.md)) are text.',
    parameters='**decimals** (`int`)\n    The number of decimals, 0 to 8.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='readback', text='Default, set, clear. A new axis has no setting (`auto_tick_decimals` is empty); the call stores the count and `clear_y_auto_tick_decimals()` removes it.',
             code='auto fig = studio("y_decimals_readback");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nauto show = [&] { const auto& v = pane.y_axis().auto_tick_decimals; std::cout << (v ? std::to_string(*v) : std::string("none")) << "\\n"; };\nstd::cout << "new axis: "; show();\npane.y_auto_tick_decimals(2);\nstd::cout << "after y_auto_tick_decimals(2): "; show();\npane.clear_y_auto_tick_decimals();\nstd::cout << "after clear: "; show();\nfig.save_svg("figure.svg");'),
        dict(id='effect', text='The effect. On an axis from 0 to 1 the automatic labels have one decimal by default; with 0, 1, 2 and 5 decimals they are written with that many.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nfor (int decimals : {0, 1, 2, 5}) {\nauto fig = studio("y_decimals_effect");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{0.0, 0.1234, 0.25, 0.5, 1.0});\n  pane.x_tick_labels(false);\npane.z_tick_labels(false);\n  pane.y_auto_tick_decimals(decimals);\n  std::cout << decimals << " decimals: " << texts(fig.to_svg()) << "\\n";\n}\nauto fig = studio("y_decimals_effect_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{0.0, 0.1234, 0.25, 0.5, 1.0});\npane.y_auto_tick_decimals(2);\nfig.save_svg("figure.svg");'),
        dict(id='scientific', text='Not when the axis is scientific. Values of millions are written in scientific notation by `Auto`, and a number of decimals does not change that; a plain-number format is the way to write them out.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto build = [&](bool decimals) {\n  auto fig = studio("y_decimals_sci");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{1200, 34000, 560000, 7800000, 9000000});\n  pane.x_tick_labels(false);\npane.z_tick_labels(false);\n  if (decimals) pane.y_auto_tick_decimals(4);\n  return fig.to_svg();\n};\nstd::cout << "no setting: " << texts(build(false)) << "\\n";\nstd::cout << "4 decimals: " << texts(build(true)) << "\\n";\nauto fig = studio("y_decimals_sci_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{1200, 34000, 560000, 7800000, 9000000});\nfig.save_svg("figure.svg");'),
        dict(id='invalid', text='Only 0 to 8 decimals. A negative count and a count above 8 are refused with `pluss::Error`, and the stored count is kept; 0 and 8 are valid.',
             code='auto fig = studio("y_decimals_invalid");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_auto_tick_decimals(3);\nfor (int bad : {-1, 9, 100}) {\n  try {\n    pane.y_auto_tick_decimals(bad);\n  } catch (const pluss::Error& e) {\n    std::cout << bad << ": " << e.message() << "\\n";\n  }\n}\npane.y_auto_tick_decimals(0);\npane.y_auto_tick_decimals(8);\nstd::cout << "0 and 8 accepted, stored: " << *pane.y_axis().auto_tick_decimals << "\\n";\npane.y_auto_tick_decimals(3);\nstd::cout << "kept after errors: " << *pane.y_axis().auto_tick_decimals << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='clear_restores', text='Clearing restores the default exactly. After `clear_y_auto_tick_decimals()` the figure equals the one that never set a count.',
             code='auto build = [&](bool set_then_clear) {\n  auto fig = studio("y_decimals_clear");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0.0, 0.25, 0.5, 1.0});\n  if (set_then_clear) pane.y_auto_tick_decimals(5).clear_y_auto_tick_decimals();\n  return fig.to_svg();\n};\nstd::cout << "equal: " << (build(true) == build(false)) << "\\n";\nauto fig = studio("y_decimals_clear_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{0.0, 0.25, 0.5, 1.0});\nfig.save_svg("figure.svg");'),
    ],
    notes='- `y_auto_tick_decimals` throws, so it is not `noexcept`; `clear_y_auto_tick_decimals` never throws.',
    see=['[`Pane::y_tick_format`](y_tick_format.md): the notation of the labels.', '[`Pane::y_ticks`](y_ticks.md): explicit labels.', '[`Pane::x_auto_tick_decimals`](x_auto_tick_decimals.md): the same setting for the x axis.', '[`Pane::z_auto_tick_decimals`](z_auto_tick_decimals.md): the same setting for the z axis.'],
)
